package com.termux.app.workspace;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import com.termux.R;import com.termux.app.TermuxActivity;import com.termux.terminal.TerminalSession;import java.lang.reflect.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentModelValuesTest {
 void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void update(Object o)throws Exception{Method m=o.getClass().getDeclaredMethod("update");m.setAccessible(true);m.invoke(o);}
 TermuxActivity activity(){TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);WorkspaceLanguage.select(a,"ru");return a;}
 TextView row(String tag){return ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView().findViewWithTag("agent-status-"+tag);}
 void open(Object ui,String method,WorkspaceStore.Session p)throws Exception{Method m=ui.getClass().getDeclaredMethod(method,WorkspaceStore.Session.class,boolean.class);m.setAccessible(true);m.invoke(ui,p,true);}
 @Test public void claudeCurrentValuesAndChangesMatchComposerAndUnsupportedEffortIsHidden()throws Exception{TermuxActivity a=activity();WorkspaceStore.Session p=new WorkspaceStore.Session();p.claudeAgent=true;ClaudeLiveUi ui=new ClaudeLiveUi(a,()->p,()->false,(x,y,z,w)->{});set(ui,"run",p.claudeSocketId);TextView chip=new TextView(a);chip.setTag(R.id.workspace_codex_status,Boolean.TRUE);set(ui,"chip",chip);JSONObject s=new JSONObject().put("ready",true).put("state","idle").put("model","actual-sonnet").put("effort","medium").put("effortOptions",new JSONArray().put("medium").put("high"));set(ui,"status",s);try{open(ui,"menu",p);assertEquals("Модель: actual-sonnet ›",row("model").getText().toString());assertTrue(chip.getText().toString().contains("actual-sonnet"));assertTrue(row("reasoning").getText().toString().contains("Средний"));s.put("model","actual-opus").put("effort","high");update(ui);assertTrue(chip.getText().toString().contains("actual-opus"));assertTrue(row("model").getText().toString().contains("actual-opus"));assertTrue(chip.getText().toString().contains("Высокий"));assertTrue(row("reasoning").getText().toString().contains("Высокий"));s.put("effortOptions",new JSONArray());update(ui);assertEquals(View.GONE,row("reasoning").getVisibility());}finally{ui.close();}}
 @Test public void geminiShowsActualThinkingAndFallbackWithoutInventedValues()throws Exception{TermuxActivity a=activity();WorkspaceStore.Session p=new WorkspaceStore.Session();p.geminiAgent=true;GeminiLiveUi ui=new GeminiLiveUi(a,()->p,()->false);set(ui,"run",p.geminiSocketId);TextView chip=new TextView(a);chip.setTag(R.id.workspace_codex_status,Boolean.TRUE);set(ui,"chip",chip);GeminiLiveStatus s=new GeminiLiveStatus();s.available=true;s.model="actual-gemini";s.thinking="high";s.thinkingEffective=true;s.canChangeThinking=true;s.state="idle";s.thinkingOptions.add("high");set(ui,"status",s);try{open(ui,"details",p);assertTrue(row("model").getText().toString().contains(s.model));assertTrue(row("reasoning").getText().toString().contains("Высокий"));assertTrue(chip.getText().toString().contains("Высокий"));s.model="actual-next";s.thinking="low";update(ui);assertTrue(row("model").getText().toString().contains("actual-next"));assertTrue(chip.getText().toString().contains("actual-next"));assertTrue(row("reasoning").getText().toString().contains("Низкий"));s.model="";s.thinkingEffective=false;update(ui);assertTrue(row("model").getText().toString().contains("По профилю CLI"));assertTrue(row("reasoning").getText().toString().contains("По профилю CLI"));s.canChangeThinking=false;update(ui);assertEquals("Unsupported control stays hidden even if option metadata remains",View.GONE,row("reasoning").getVisibility());s.canChangeThinking=true;s.thinkingOptions.clear();update(ui);assertEquals(View.GONE,row("reasoning").getVisibility());}finally{ui.close();}}
 @Test public void openCodeActualModelVariantUsesCatalogAndNoInferenceRequests()throws Exception{TermuxActivity a=activity();WorkspaceStore.Session p=new WorkspaceStore.Session();p.aiAgent="opencode";List<String> calls=new java.util.concurrent.CopyOnWriteArrayList<>();JSONObject actual=new JSONObject().put("providerID","local").put("id","actual-model").put("variant","high");OpenCodeStatusUi ui=new OpenCodeStatusUi(a,p,()->fail("no mutation"),q->{calls.add(q.optString("op"));if(q.optString("op").equals("status"))return new JSONObject().put("model",actual);return new JSONObject().put("models",new JSONArray().put(new JSONObject().put("provider","local").put("id","actual-model").put("variants",new JSONArray().put(new JSONObject().put("id","high")))));});try{ui.showModels();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();for(int i=0;i<200;i++){Thread.sleep(5);Shadows.shadowOf(Looper.getMainLooper()).idle();if(d.getButton(-1).isEnabled())break;}assertEquals("Модель: actual-model ›",row("model").getText().toString());assertEquals("Рассуждение: high",row("reasoning").getText().toString());assertTrue(AiAgentsUi.sessionModelLabel(p,actual).contains("actual-model · high"));assertEquals(Arrays.asList("status","models"),calls);actual.put("id","next").put("variant","low");Method refresh=OpenCodeStatusUi.class.getDeclaredMethod("refresh");refresh.setAccessible(true);refresh.invoke(ui);for(int i=0;i<200;i++){Thread.sleep(5);Shadows.shadowOf(Looper.getMainLooper()).idle();if(d.getButton(-1).isEnabled())break;}assertEquals("Модель: next ›",row("model").getText().toString());assertEquals(View.GONE,row("reasoning").getVisibility());}finally{ShadowAlertDialog.getLatestAlertDialog().dismiss();}}
 @Test public void codexWindowTracksStatusAndComposerValuesForSelectedRun()throws Exception{TermuxActivity a=activity();a.setContentView(R.layout.activity_termux);set(a,"mTerminalView",a.findViewById(R.id.terminal_view));WorkspaceController c=new WorkspaceController(a);WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="codex";TerminalSession fake=new TerminalSession("unused","unused",new String[0],new String[0],2000,null);p.handle=fake.mHandle;WorkspaceStore store=(WorkspaceStore)get(c,"store");store.sessions.add(p);a.getTerminalView().mTermSession=fake;CodexStatus s=new CodexStatus();s.model="actual-codex";s.effort="high";s.models.put(new JSONObject().put("model",s.model).put("supportedReasoningEfforts",new JSONArray().put("high")));((Map<String,CodexStatus>)get(c,"codexStatuses")).put(p.id,s);try{Method show=c.getClass().getDeclaredMethod("showCodexModels",WorkspaceStore.Session.class);show.setAccessible(true);show.invoke(c,p);assertEquals("Модель: actual-codex",row("model").getText().toString());assertTrue(row("reasoning").getText().toString().contains("Высокий"));s.model="actual-next";s.effort="medium";s.models.put(new JSONObject().put("model",s.model).put("supportedReasoningEfforts",new JSONArray().put("medium")));((Runnable)get(c,"codexModelsUpdate")).run();assertEquals("Модель: actual-next",row("model").getText().toString());assertTrue(row("reasoning").getText().toString().contains("Средний"));}finally{a.getTerminalView().mTermSession=null;c.close();}}
}
